CREATE COLUMN TABLE "TEST_AP"."UICU" ("TPLId" SMALLINT CS_INT NOT NULL , "TPLName" NVARCHAR(155) NOT NULL , "TPLDesc" NVARCHAR(155), "UserID" SMALLINT CS_INT, "Parent" SMALLINT CS_INT, "IsTemplate" NVARCHAR(1), PRIMARY KEY ("TPLId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "UICU_NAME_KEY" ON "TEST_AP"."UICU" ( "TPLName" ASC )